/**
 * Detect — from the generated bytes alone — which engine actually produced a
 * PDF artifact. This is not a claim about configuration: it inspects the real
 * document metadata embedded in the file.
 *
 *   - pdf-lib sets `Producer: pdf-lib (https://github.com/Hopding/pdf-lib)`.
 *   - Chromium (Playwright print-to-PDF) reports `Producer: Skia/PDF m###`.
 *
 * The document tool exposes this as `renderEngine`, so a deployed Vercel
 * instance can be verified live: a real Chromium render shows up as
 * `chromium`, while the lightweight fallback honestly shows as `pdf-lib`.
 */

export type RenderEngine = 'chromium' | 'pdf-lib' | 'unknown'

export async function detectRenderEngine(buffer: Buffer): Promise<RenderEngine> {
  try {
    const { PDFDocument } = await import('pdf-lib')
    const pdf = await PDFDocument.load(new Uint8Array(buffer), {
      ignoreEncryption: true,
      updateMetadata: false
    })
    const producer = (pdf.getProducer() ?? '').toLowerCase()
    if (producer.includes('pdf-lib')) return 'pdf-lib'
    if (producer.includes('skia')) return 'chromium'
    if (producer.includes('chromium') || producer.includes('chrome'))
      return 'chromium'
    return 'unknown'
  } catch {
    // Not a readable PDF (or pdf-lib import failed) — no honest verdict.
    return 'unknown'
  }
}
